      return;
    }

  sample = sf32lb52_button_readset();
  if (sample == priv->last_sample)
    {
      return;
    }

  priv->last_sample = sample;

  if (priv->handler != NULL)
    {
      priv->handler(&priv->lower, priv->arg);
    }
}

