              lv_label_set_text(lbl, "Sed ON");
            }
        }
    }
}

static void button_event_cb(int key, int is_long_press)
{
  if (is_long_press)
    {
      printf("[btn] KEY2 long: toggle sedentary\n");
      lv_async_call(async_ui_update, (void *)2);
    }
  else
